set -e
printf '%s' '' | base64 -d > /tmp/ja3cap.py
cat > /tmp/cap.sh <<'SH'
#!/usr/bin/env bash
set -euo pipefail
IFACE="${1:?usage: cap.sh IFACE MAX SECONDS [--anonymise]}"
MAX="${2:-5000}"
SECS="${3:-300}"
EXTRA="${4:-}"
HOSTIP="${HOSTIP:-209.192.191.68}"

command -v tcpdump >/dev/null || { echo "tcpdump not installed" >&2; exit 1; }

# Filter notes:
#   dst host $HOSTIP  -> INBOUND only. Without this the capture records the
#                        ADX's own outbound TLS connections to exchanges,
#                        which are a completely different population.
#   no flag guard     -> SYN carries 0x02 (SYN), not 0x10 (ACK), so any
#                        flag-based "payload" test either drops the handshake
#                        or keeps everything. The Python parser ignores
#                        payload-less packets itself, so keep the filter simple.
#   -s 0              -> keep the whole frame.
tcpdump -i "$IFACE" -nn -s 0 -U -w - \
  "tcp dst port 443 and dst host $HOSTIP" 2>/dev/null \
  | python3 /tmp/ja3cap.py "$MAX" "$SECS" $EXTRA
SH
chmod +x /tmp/cap.sh
/tmp/cap.sh "$@"
